import {Matrix4,Vector4,RenderTarget,HalfFloatType,Vector2} from 'three/webgpu';
import * as T from 'three/tsl';
import {ScreenFrameState} from './screen-effects.js';

export function gpuSurfaceOutputs(){const normal=T.Fn((_,builder)=>{const material=builder.context.material;return material.isMeshStandardNodeMaterial&&!material.transparent?T.vec4(T.normalWorld.mul(.5).add(.5),T.roughness):T.vec4(.5,.5,.5,1);}),albedo=T.Fn((_,builder)=>{const material=builder.context.material;return material.isMeshStandardNodeMaterial&&!material.transparent?T.vec4(T.diffuseColor.rgb,T.metalness):T.vec4(0);});return T.mrt({output:T.output,hbSurfaceNormal:normal(),hbSurfaceAlbedo:albedo()});}

export function installGpuSurfaceKeys(scene,renderer){scene.traverse(object=>{for(const material of Array.isArray(object.material)?object.material:[object.material]){if(!material)continue;material.userData.hbSurfaceRenderer=renderer;if(material.userData.hbSurfaceKey)continue;material.userData.hbSurfaceKey=true;const key=material.customProgramCacheKey.bind(material);material.customProgramCacheKey=()=>key()+':hb-mrt:'+Object.keys(material.userData.hbSurfaceRenderer.getMRT()?.outputNodes||{}).sort().join(',');material.needsUpdate=true;}});}

export function gpuScreenEffects(color,depth,surfaceNormal,surfaceAlbedo,renderer){
 const u={};for(const key of ['temporal','motion','reflection','indirect','coordinates','jitter','eye','forward','camera'])u[key]=T.uniform(new Vector4());for(const key of ['inverseVP','currentVP','previousVP'])u[key]=T.uniform(new Matrix4());u.size=T.uniform(new Vector2());
 const state=new ScreenFrameState(),history=new RenderTarget(1,1,{type:HalfFloatType,depthBuffer:false}),previous=T.texture(history.texture),uv=T.uv();let width=0,height=0,frame;
 const linear=d=>u.camera.z.greaterThan(.5).select(T.mix(u.camera.x,u.camera.y,d),u.camera.x.mul(u.camera.y).div(u.camera.y.sub(d.mul(u.camera.y.sub(u.camera.x))).max(.000001)));
 const worldAt=T.Fn(([at,d])=>{const q=u.inverseVP.mul(T.vec4(at.x.mul(2).sub(1),at.y.mul(u.coordinates.z).add(u.coordinates.w),d.mul(u.coordinates.x).add(u.coordinates.y),1));return q.xyz.div(q.w);});
 const project=T.Fn(([p,vp])=>{const q=vp.mul(T.vec4(p,1)),n=q.xyz.div(q.w);return T.vec3(n.x.mul(.5).add(.5),n.y.sub(u.coordinates.w).div(u.coordinates.z),n.z.sub(u.coordinates.y).div(u.coordinates.x));});
 const inside=at=>at.greaterThan(0).all().and(at.lessThan(1).all());
 const ray=T.Fn(([p,direction])=>{const result=T.vec4(0).toVar();T.Loop({start:1,end:65,type:'int',condition:'<'},({i})=>{T.If(T.float(i).greaterThan(u.indirect.y),()=>T.Break());const at=project(p.add(direction.mul(T.float(i).mul(u.reflection.z.div(u.indirect.y)))),u.currentVP).toVar();T.If(inside(at).not(),()=>T.Break());const d=depth.sample(at.xy).r;T.If(d.greaterThanEqual(.99999),()=>T.Continue());const difference=linear(at.z).sub(linear(d));T.If(difference.greaterThan(0).and(difference.lessThan(u.reflection.w)),()=>{const n=surfaceNormal.sample(at.xy).xyz.mul(2).sub(1);T.If(n.dot(n).lessThan(.5).or(n.dot(direction).lessThan(-.05)),()=>{const border=T.min(T.min(at.x,T.float(1).sub(at.x)),T.min(at.y,T.float(1).sub(at.y)));result.assign(T.vec4(color.sample(at.xy).rgb,border.smoothstep(0,.08).mul(T.float(1).sub(T.float(i).div(u.indirect.y)))));T.Break();});});});return result;});
 const resolve=T.Fn(()=>{const original=color.sample(uv),d=depth.sample(uv).r,p=worldAt(uv,d),c=original.rgb.toVar();
  if(surfaceNormal){const nr=surfaceNormal.sample(uv),am=surfaceAlbedo.sample(uv),normal=nr.xyz.mul(2).sub(1);T.If(d.lessThan(.99999).and(normal.dot(normal).greaterThan(.5)),()=>{const n=normal.normalize(),incident=u.eye.w.greaterThan(.5).select(u.forward.xyz,p.sub(u.eye.xyz).normalize()),start=p.add(n.mul(T.min(.05,u.reflection.w.mul(.25))));T.If(u.reflection.x.greaterThan(0).and(nr.w.lessThan(u.reflection.y)),()=>{const hit=ray(start,incident.reflect(n)),f0=T.mix(T.vec3(.04),am.rgb,am.a),f=f0.add(T.vec3(1).sub(f0).mul(T.float(1).sub(n.dot(incident.negate()).max(0)).pow(5))),fade=T.float(1).sub(nr.w.smoothstep(u.reflection.y.mul(.75),u.reflection.y));c.assign(T.mix(c,c.mul(T.vec3(1).sub(f)).add(hit.rgb.mul(f)),hit.a.mul(u.reflection.x).mul(fade)));});
   T.If(u.indirect.x.greaterThan(0),()=>{const tangent=n.cross(n.z.abs().lessThan(.9).select(T.vec3(0,0,1),T.vec3(0,1,0))).normalize(),bitangent=n.cross(tangent),sum=T.vec3(0).toVar();T.Loop(4,({i})=>{const a=T.float(i).mul(1.570796327).add(.392699),direction=n.mul(.70710678).add(tangent.mul(a.cos()).add(bitangent.mul(a.sin())).mul(.70710678)).normalize(),hit=ray(start,direction);sum.addAssign(hit.rgb.mul(hit.a));});c.addAssign(sum.mul(.25).mul(am.rgb).mul(T.float(1).sub(am.a)).mul(u.indirect.x));});});}
  const at=project(p,u.previousVP);T.If(u.temporal.w.greaterThan(.5).and(d.lessThan(.99999)).and(inside(at)),()=>{
   T.If(u.motion.x.greaterThan(0),()=>{const velocity=uv.sub(at.xy).sub(u.jitter.xy).add(u.jitter.zw).mul(u.motion.x).toVar();velocity.mulAssign(T.min(1,u.motion.y.div(velocity.length().max(.000001))));const sum=c.toVar(),total=T.float(1).toVar();T.Loop({start:1,end:16,type:'int',condition:'<'},({i})=>{T.If(T.float(i).greaterThanEqual(u.motion.z),()=>T.Break());const sampleUV=uv.add(velocity.mul(T.float(i).div(u.motion.z.sub(1).max(1)).sub(.5))).clamp(0,1),other=depth.sample(sampleUV).r;T.If(linear(other).sub(linear(d)).abs().lessThan(T.max(.05,linear(d).mul(.02))),()=>{sum.addAssign(color.sample(sampleUV).rgb);total.addAssign(1);});});c.assign(sum.div(total));});
   T.If(u.temporal.x.greaterThan(0),()=>{const old=previous.sample(at.xy),expected=linear(at.z);T.If(old.a.exp2().sub(expected).abs().lessThan(T.max(.02,expected.mul(u.temporal.z))),()=>{const lo=c.toVar(),hi=c.toVar();T.Loop({start:-1,end:2,type:'int',condition:'<'},({i:y})=>{T.Loop({start:-1,end:2,type:'int',condition:'<'},({i:x})=>{const neighbor=color.sample(uv.add(T.vec2(x,y).div(u.size)).clamp(0,1)).rgb.add(c).sub(original.rgb);lo.assign(T.min(lo,neighbor));hi.assign(T.max(hi,neighbor));});});c.assign(T.mix(c,old.rgb.clamp(lo,hi),u.temporal.x.mul(u.temporal.y)));});});
  });return T.vec4(c.max(0),linear(d).log2());
 });
 const resolved=T.rtt(resolve(),null,null,{type:HalfFloatType,depthBuffer:false});
 return {node:T.vec4(resolved.rgb,color.a),prepare(p,time,camera,scene){const size=renderer.getDrawingBufferSize(new Vector2());if(width!==size.x||height!==size.y){width=size.x;height=size.y;history.setSize(width,height);state.reset();}if(camera.coordinateSystem!==renderer.coordinateSystem){camera.coordinateSystem=renderer.coordinateSystem;camera.updateProjectionMatrix();}frame=state.begin(camera,p,width,height,time,scene,renderer.coordinateSystem===2001);for(const [key,value]of Object.entries(frame.packed))if(u[key])u[key].value.fromArray(value);u.camera.value.set(camera.near,camera.far,camera.isOrthographicCamera?1:0,1);},after(){renderer.copyTextureToTexture(resolved.value,history.texture);frame?.end();frame=null;},failed(){frame?.end(false);frame=null;},dispose(){resolved.renderTarget.dispose();resolved._quadMesh?.material.dispose();history.dispose();state.reset();}};
}
